"""Bounded TShark dissection. All input paths are generated by the application."""
from collections import Counter
from dataclasses import dataclass
from decimal import Decimal
from pathlib import Path
import subprocess
import tempfile

TSHARK = "/usr/bin/tshark"
MAX_PACKETS = 50000
MAGICS = {bytes.fromhex(x) for x in ["a1b2c3d4", "d4c3b2a1", "a1b23c4d", "4d3cb2a1", "0a0d0d0a"]}
FIELDS = """frame.number frame.time_epoch frame.len frame.cap_len frame.interface_id
frame.protocols vlan.id ip.src ip.dst ipv6.src ipv6.dst ip.flags.mf ip.frag_offset
ipv6.fraghdr.offset tcp.srcport tcp.dstport udp.srcport udp.dstport tcp.flags tcp.stream
udp.stream tcp.seq_raw icmp.type icmp.ident icmpv6.type icmpv6.echo.identifier""".split()


@dataclass(slots=True)
class Packet:
    frame: int
    ns: int
    src: str
    dst: str
    sport: int | None
    dport: int | None
    proto: str
    length: int
    flags: int | None
    stream: str
    seq: str
    circuit: tuple
    echo_reply: bool
    truncated: bool


def validate_capture(path):
    with Path(path).open("rb") as file:
        if file.read(4) not in MAGICS:
            raise ValueError("Unsupported capture signature. Supply an uncompressed PCAP or PCAPNG file.")


def parse(line):
    parts = line.rstrip("\n\r").split("\t")
    if len(parts) != len(FIELDS):
        raise ValueError("Unexpected TShark field layout")
    f = dict(zip(FIELDS, parts))
    stack = f["frame.protocols"].split(":")
    if stack.count("ip") + stack.count("ipv6") != 1:
        return None, "non-IP or encapsulated"
    if f["ip.flags.mf"] in {"1", "True"} or int(f["ip.frag_offset"] or 0) or f["ipv6.fraghdr.offset"]:
        return None, "fragmented"
    src, dst = (f["ip.src"] or f["ipv6.src"]), (f["ip.dst"] or f["ipv6.dst"])
    sport = dport = flags = None
    reply = False
    if "icmp" in stack or "icmpv6" in stack:
        proto = "icmp" if "icmp" in stack else "icmpv6"
        kind = f[f"{proto}.type"]
        if kind not in ({"0", "8"} if proto == "icmp" else {"128", "129"}):
            return None, "non-echo ICMP"
        reply = kind in {"0", "129"}
        stream = f["icmp.ident"] or f["icmpv6.echo.identifier"]
        if not stream:
            return None, "incomplete echo header"
    elif "tcp" in stack or "udp" in stack:
        proto = "tcp" if "tcp" in stack else "udp"
        if not (f[f"{proto}.srcport"] and f[f"{proto}.dstport"]):
            return None, "incomplete transport header"
        sport, dport = int(f[f"{proto}.srcport"]), int(f[f"{proto}.dstport"])
        stream = f[f"{proto}.stream"]
        if proto == "tcp":
            if not f["tcp.flags"]:
                return None, "incomplete TCP flags"
            flags = int(f["tcp.flags"], 0)
    else:
        return None, "unsupported IP transport"
    if not src or not dst:
        return None, "incomplete IP header"
    length = int(f["frame.len"])
    return Packet(int(f["frame.number"]), int(Decimal(f["frame.time_epoch"]) * 10**9),
                  src, dst, sport, dport, proto, length, flags, stream, f["tcp.seq_raw"],
                  (f["frame.interface_id"], f["vlan.id"]), reply, int(f["frame.cap_len"]) < length), None


def extract(path, consume, max_packets=MAX_PACKETS):
    validate_capture(path)
    args = [TSHARK, "-n", "-r", str(path), "-c", str(max_packets + 1), "-T", "fields",
            "-E", "occurrence=f"]
    for field in FIELDS:
        args.extend(["-e", field])
    skipped = Counter()
    total = 0
    with tempfile.TemporaryFile("w+") as output, tempfile.TemporaryFile("w+") as errors:
        try:
            proc = subprocess.run(args, stdout=output, stderr=errors, timeout=100, check=False)
        except subprocess.TimeoutExpired as exc:
            raise ValueError("Packet extraction exceeded 100 seconds") from exc
        if proc.returncode:
            raise ValueError(f"TShark could not read this capture (exit {proc.returncode}). Check file integrity.")
        output.seek(0)
        for total, line in enumerate(output, start=1):
            if total > max_packets:
                raise ValueError(f"Capture exceeds {max_packets:,} frames. Split it in Wireshark.")
            p, reason = parse(line)
            if p is None:
                skipped[reason] += 1
            else:
                consume(p)
    return total, skipped
